    const getHeaderHtml = (title) => `
        <div class="header">
            <h1>${schoolInfo.name}</h1>
            <h3>${schoolInfo.year} Eğitim Öğretim Yılı</h3>
            <h2>${title}</h2>
        </div>
    `;

    const getSignatureHtml = (rowKey = null) => {
        let teacherHtml = '';
        if (isTeacher && !isGenel && rowKey) {
            teacherHtml = `
               <td colspan="2" style="border: none; text-align: left; vertical-align: bottom;">
                 <strong>Aslını elden teslim aldım.</strong><br/>
                 Tarih: ...../...../20....<br/><br/><br/>
                 ${rowKey}
               </td>
            `;
        } else {
            teacherHtml = `<td colspan="2" style="border: none;"></td>`;
        }

        if (forExcel) {
            // How many columns total? 1 for SAAT + activeDays.length
            const totalCols = activeDays.length + 1;
            // Distribute across totalCols. Let's say we have 6 columns.
            // teacherHtml can take 2, vice takes 2, principal takes 2.
            // We just use colspan.
            const col1 = Math.floor(totalCols / 3) || 1;
            const col2 = Math.floor(totalCols / 3) || 1;
            const col3 = totalCols - col1 - col2;

            let tHtml = '';
            if (isTeacher && !isGenel && rowKey) {
                tHtml = `
                   <td colspan="${col1}" style="border: none; text-align: left; vertical-align: bottom; font-size: 14px;">
                     <br/><br/>
                     <strong>Aslını elden teslim aldım.</strong><br/>
                     Tarih: ...../...../20....<br/><br/><br/><br/>
                     <strong>${rowKey}</strong>
                   </td>
                `;
            } else {
                tHtml = `<td colspan="${col1}" style="border: none;"></td>`;
            }

            return `
              <tr style="border: none;">
                 ${tHtml}
                 <td colspan="${col2}" style="border: none; text-align: center; vertical-align: bottom; font-size: 14px;">
                    <br/><br/>
                    <strong>Müdür Yardımcısı</strong><br/><br/><br/><br/><strong>${schoolInfo.vicePrincipal || '...........................'}</strong>
                 </td>
                 <td colspan="${col3}" style="border: none; text-align: center; vertical-align: bottom; font-size: 14px;">
                    <br/><br/>
                    <strong>Okul Müdürü</strong><br/><br/><br/><br/><strong>${schoolInfo.principal || '...........................'}</strong>
                 </td>
              </tr>
            `;
        } else {
            return `
            <table style="width: 100%; border: none; margin-top: auto; page-break-inside: avoid; font-size: 13px;">
               <tr style="border: none;">
                  <td style="border: none; width: 33%; text-align: left; vertical-align: bottom;">
                     ${isTeacher && !isGenel && rowKey ? `<strong>Aslını elden teslim aldım.</strong><br/><br/>Tarih: ...../...../20....<br/><br/><br/><strong>${rowKey}</strong>` : ''}
                  </td>
                  <td style="border: none; width: 33%; text-align: center; vertical-align: bottom;">
                     <strong>Müdür Yardımcısı</strong><br/><br/><br/><br/><strong>${schoolInfo.vicePrincipal || '...........................'}</strong>
                  </td>
                  <td style="border: none; width: 33%; text-align: right; vertical-align: bottom;">
                     <strong>Okul Müdürü</strong><br/><br/><br/><br/><strong>${schoolInfo.principal || '...........................'}</strong>
                  </td>
               </tr>
            </table>
            `;
        }
    };

    if (isGenel) {
       htmlContent += `<div class="page-container">`;
       htmlContent += getHeaderHtml(`Genel ${reportTitle} Programı`);
       htmlContent += `<table class="genel-table"><thead><tr><th rowspan="2" class="row-header">${reportTitle}</th>`;
       activeDays.forEach(day => htmlContent += `<th colspan="${day.periods}">${day.name}</th>`);
       htmlContent += `</tr><tr>`;
       activeDays.forEach(day => {
         for(let i=0; i<day.periods; i++) {
           htmlContent += `<th>${i+1}<br/><span class="time-header">${schoolSettings.lessonTimes[i].start}</span></th>`;
         }
       });
       htmlContent += `</tr></thead><tbody>`;

       rowKeys.forEach(rowKey => {
         htmlContent += `<tr><td class="row-header text-cell">${rowKey}</td>`;
         activeDays.forEach((day, dIdx) => {
           for(let i=0; i<day.periods; i++) {
             const valStr = dataMaster[rowKey]?.[dIdx]?.[i];
             let displayVal = '';
             if(valStr && valStr !== '') {
                 const cData = parseCellData(valStr);
                 if (cData) {
                     let mainE = isTeacher ? cData.classes.join(', ') : isClass ? cData.teachers.join(', ') : cData.classes.join(', ');
                     let subE = cData.rooms?.length > 0 ? cData.rooms.join(', ') : '';

                     if (forExcel) {
                         displayVal = `<div style="font-weight:bold; font-size:12px;">${mainE}</div><div style="color:#444; font-size:11px;">${cData.subject}</div>${subE ? `<div style="color:#666; font-size:10px; font-style:italic;">${subE}</div>` : ''}`;
                     } else {
                         displayVal = `<div class="cell-content"><span class="main-text">${mainE}</span><span class="sub-text">${cData.subject}</span>${subE ? `<span class="room-text">${subE}</span>` : ''}</div>`;
                     }
                 }
             }
             htmlContent += `<td class="text-cell">${displayVal}</td>`;
           }
         });
         htmlContent += `</tr>`;
       });

       if (forExcel) {
           htmlContent += getSignatureHtml();
           htmlContent += `</tbody></table></div>`;
       } else {
           htmlContent += `</tbody></table>`;
           htmlContent += getSignatureHtml();
           htmlContent += `</div>`;
       }

    } 
    else {
       rowKeys.forEach((key, index) => {
         htmlContent += `<div class="page-container">`;
         htmlContent += getHeaderHtml(`${key} - ${reportTitle} El Programı`);
         htmlContent += `<table><thead><tr><th class="row-header">SAAT</th>`;
         activeDays.forEach(day => htmlContent += `<th>${day.name}</th>`);
         htmlContent += `</tr></thead><tbody>`;

         for(let pIdx=0; pIdx<maxPeriods; pIdx++) {
           htmlContent += `<tr><td class="row-header text-cell">${pIdx+1}. Ders<br/><span class="time-header">${schoolSettings.lessonTimes[pIdx].start} - ${schoolSettings.lessonTimes[pIdx].end}</span></td>`;
           activeDays.forEach((day, dIdx) => {
             if (pIdx < day.periods) {
               const valStr = dataMaster[key]?.[dIdx]?.[pIdx];
