         } else {
             htmlContent += `</tbody></table>`;
             htmlContent += getSignatureHtml(key);
             htmlContent += `</div>`;
         }


         if (forExcel && index < rowKeys.length - 1) {
            htmlContent += `<table><tr class="empty-row"><td colspan="${activeDays.length + 1}"></td></tr></table><br/><br/>`;
