    htmlContent += `</body></html>`;
    return htmlContent;
  };

  const ejectCellIfOccupied = (typeKey, entityName, dIdx, pIdx) => {
      let ejectedCount = 0;
      const ejectedVals = new Set();

      setSchedules(prevTSched => {
          const tSched = JSON.parse(JSON.stringify(prevTSched));

          setClassSchedules(prevCSched => {
              const cSched = JSON.parse(JSON.stringify(prevCSched));

              setRoomSchedules(prevRSched => {
                  const rSched = JSON.parse(JSON.stringify(prevRSched));

                  setUnplacedCourses(prevPool => {
                      let pool = [...prevPool];

                      const checkAndEject = (valStr) => {
                          if (!valStr || valStr === '' || ejectedVals.has(valStr)) return;

                          const cData = parseCellData(valStr);
                          if (!cData) return;

                          const t = cData.teachers[0];
                          if (!tSched[t]) return;

                          ejectedVals.add(valStr); // Prevent multiple ejections of the same block

                          let pStart = pIdx;
                          while(pStart > 0 && tSched[t][dIdx][pStart - 1] === valStr) pStart--;

                          let blockSize = 1;
                          while(pStart + blockSize < schoolSettings.weekDays[dIdx].periods && tSched[t][dIdx][pStart + blockSize] === valStr) blockSize++;

                          if (tSched[t][dIdx][pStart] === '') return; 

                          for(let i=0; i<blockSize; i++) {
                              cData.teachers.forEach(tx => { if(tSched[tx]) tSched[tx][dIdx][pStart+i] = ''; });
                              cData.classes.forEach(cx => { if(cSched[cx]) cSched[cx][dIdx][pStart+i] = ''; });
                              cData.rooms?.forEach(rx => { if(rSched[rx]) rSched[rx][dIdx][pStart+i] = ''; });
                          }

                          pool.push({
                              id: generateId(),
                              teachers: cData.teachers,
                              classes: cData.classes,
                              rooms: cData.rooms || [],
                              subject: cData.subject,
                              hours: blockSize,
                              failCount: 0
                          });
                          ejectedCount++;
                      };

                      if (typeKey === 'teachers' && tSched[entityName]?.[dIdx]?.[pIdx]) checkAndEject(tSched[entityName][dIdx][pIdx]);
                      else if (typeKey === 'classes' && cSched[entityName]?.[dIdx]?.[pIdx]) checkAndEject(cSched[entityName][dIdx][pIdx]);
                      else if (typeKey === 'rooms' && rSched[entityName]?.[dIdx]?.[pIdx]) checkAndEject(rSched[entityName][dIdx][pIdx]);
                      else if (typeKey === 'subjects') {
                          Object.keys(tSched).forEach(t => {
                              const val = tSched[t]?.[dIdx]?.[pIdx];
                              if (val) {
                                 const cData = parseCellData(val);
                                 if (cData && cData.subject === entityName) checkAndEject(val);
                              }
                          });
                      }

                      return pool;
                  });
                  return rSched;
              });
              return cSched;
          });
          return tSched;
      });

      if (ejectedCount > 0) {
          setTimeout(() => { showToast(`Koşul kapatıldığı için çakışan ${ejectedCount} ders havuza alındı.`, "info"); }, 50);
      }
  };

  const toggleSpecificConstraint = (typeKey, name, dIdx, pIdx, forceClosedState) => {
    const key = `${dIdx}-${pIdx}`;
    let isClosing = false;

    setConstraints(prev => {
       const newConst = {...prev};
       if (!newConst[typeKey][name]) newConst[typeKey][name] = [];
       let list = newConst[typeKey][name];

       if (forceClosedState === true && !list.includes(key)) {
           list.push(key);
           isClosing = true;
       }
       else if (forceClosedState === false && list.includes(key)) {
           list = list.filter(k => k !== key);
       }
       newConst[typeKey][name] = list;
       return newConst;
    });

    if (isClosing || forceClosedState === true) {
       ejectCellIfOccupied(typeKey, name, dIdx, pIdx);
    }
  };

  const toggleDayConstraints = (typeKey, name, dIdx, periods) => {
    const allClosed = Array.from({length: periods}).every((_, p) => constraints[typeKey][name]?.includes(`${dIdx}-${p}`));
    for(let p = 0; p < periods; p++) toggleSpecificConstraint(typeKey, name, dIdx, p, !allClosed); 
  };


  const printSchedule = (type) => {
    setPrintMenuOpen(false);
    const htmlContent = generateReportHTML(type, false);
