  const workersRef = useRef([]);
  const cancelRef = useRef(false);

  const terminateWorkers = () => {
     workersRef.current.forEach(w => w.terminate());
     workersRef.current = [];
  };

  const stopDistributePro = () => {
    cancelRef.current = true;
    workersRef.current.forEach(w => w.postMessage({ type: 'stop' }));
    setDistributeState(prev => ({ ...prev, phase: 'İptal Ediliyor, En İyi Sonuç Hazırlanıyor...' }));
    showToast("Dağıtım iptal ediliyor, bulunan en iyi sonuç getiriliyor...", "info");
  };

  const autoDistributePro = () => {
    const coreCount = selectedCoreCount;
    if (unplacedCourses.length === 0) return showToast("Dağıtılacak kart havuzda yok.", "warning");

    setDistributeState({ isRunning: true, progress: 0, phase: 'Kuantum AI Motoru (' + coreCount + ' Çekirdek) Başlatılıyor...' });
    setCoreStates(Array(coreCount).fill({ progress: 0, phase: 'Hazırlanıyor...' }));

    terminateWorkers(); // clean up previous workers
    cancelRef.current = false;

    let finishedCount = 0;
    let bestResult = null;
    let bestUnplacedCount = Infinity;

    const finish = () => {
        terminateWorkers();
        if (bestResult) {
            setSchedules(bestResult.schedules);
            setClassSchedules(bestResult.classSchedules);
            setRoomSchedules(bestResult.roomSchedules);
            setUnplacedCourses(bestResult.unplacedCourses);

            setDistributeState({ isRunning: false, progress: 100, phase: 'Tamamlandı' });

            if (cancelRef.current) {
                showToast(`Dağıtım durduruldu. En iyi yerleşim (Kalan: ${bestResult.unplacedCourses.length} ders) yüklendi.`, "info");
            } else if (bestResult.unplacedCourses.length > 0) {
                showToast(`Sistem ${bestResult.iter} ihtimali taradı. Matematiksel yetersizlik / çakışmalar sebebiyle ${bestResult.unplacedCourses.length} ders yerleşemedi.`, "warning");
            } else {
                showToast(`Kusursuz! Yapay Zeka modeli milyarlarca olasılığı tarayıp ${bestResult.iter} iterasyonda 0 çatışma ile optimum programı oluşturdu.`, "success");
            }
        } else {
            setDistributeState({ isRunning: false, progress: 0, phase: '' });
            showToast("Dağıtım işlemi gerçekleştirilemedi.", "error");
        }
    };

    for(let i=0; i<coreCount; i++) {
        const worker = new Worker(new URL('./workers/quantum.ts', import.meta.url), { type: 'module' });

        worker.onmessage = (e) => {
            if (e.data.type === 'progress') {
                setCoreStates(prev => {
                    const newStates = [...prev];
                    newStates[i] = { progress: e.data.progress, phase: e.data.phase };
                    return newStates;
                });
                if (i === 0) { // only update UI from first thread to avoid flicker
                    setDistributeState({ isRunning: true, progress: e.data.progress, phase: e.data.phase + ' (Çekirdek: ' + coreCount + ')' });
                }
            } else if (e.data.type === 'done') {
                const result = e.data.payload;
                if (result.unplacedCourses.length === 0) {
                    // Found a perfect solution! Stop all workers immediately!
                    bestResult = result;
                    finish();
                } else {
                    if (result.unplacedCourses.length < bestUnplacedCount) {
                        bestUnplacedCount = result.unplacedCourses.length;
                        bestResult = result;
                    }
                    console.error('Worker error:', e.data.message); finishedCount++;
                    if (finishedCount === coreCount) {
                        finish();
                    }
                }
            } else if (e.data.type === 'error') {
                console.error('Worker error:', e.data.message); finishedCount++;
                if (finishedCount === coreCount) {
                    finish();
                }
            }
        };

        worker.postMessage({
            unplacedCourses,
            schoolSettings,
            schedules,
            classSchedules,
            roomSchedules,
            lockedCells,
            constraints,
            workerIndex: i
        });

        workersRef.current.push(worker);
    }
  };


