  const handleDropToTimetable = (e, destEntity, targetDIdx, targetPIdx, targetBlockSize, existingValue) => {
     e.preventDefault();
     const payload = JSON.parse(e.dataTransfer.getData('application/json') || "null");
     if (!payload) return;

     const newTSched = JSON.parse(JSON.stringify(schedules));
     const newCSched = JSON.parse(JSON.stringify(classSchedules));
     const newRSched = JSON.parse(JSON.stringify(roomSchedules));
     let newUnplaced = [...unplacedCourses];

     const isCardLocked = (cData, d, p, hours) => {
         for(let i=0; i<hours; i++) {
             for(let t of cData.teachers) if (lockedCells[`${t}-${d}-${p+i}`]) return true;
             for(let c of cData.classes) if (lockedCells[`${c}-${d}-${p+i}`]) return true;
         }
         return false;
     };

     const canPlaceCard = (teachers, classes, rooms, startP, hours, ignoreValStr = null) => {
         for(let i=0; i<hours; i++) {
             if (targetPIdx + i >= schoolSettings.weekDays[targetDIdx].periods) return false;
             const p = startP + i;
             for(let t of teachers) if((newTSched[t]?.[targetDIdx]?.[p] && newTSched[t]?.[targetDIdx]?.[p] !== ignoreValStr) || lockedCells[`${t}-${targetDIdx}-${p}`]) return false;
             for(let c of classes) if((newCSched[c]?.[targetDIdx]?.[p] && newCSched[c]?.[targetDIdx]?.[p] !== ignoreValStr) || lockedCells[`${c}-${targetDIdx}-${p}`]) return false;
             for(let r of rooms) if((newRSched[r]?.[targetDIdx]?.[p] && newRSched[r]?.[targetDIdx]?.[p] !== ignoreValStr) || lockedCells[`${r}-${targetDIdx}-${p}`]) return false;
         }
         return true;
     };

     const executePlacement = (cardDataStr, hours, d, p) => {
         const data = parseCellData(cardDataStr);
         if(!data) return;
         for(let i=0; i<hours; i++) {
             data.teachers.forEach(t => { if(newTSched[t]) newTSched[t][d][p+i] = cardDataStr; });
             data.classes.forEach(c => { if(newCSched[c]) newCSched[c][d][p+i] = cardDataStr; });
             data.rooms.forEach(r => { if(newRSched[r]) newRSched[r][d][p+i] = cardDataStr; });
         }
     };

     const executeRemoval = (cardDataStr, hours, d, p) => {
         const data = parseCellData(cardDataStr);
         if(!data) return;
         for(let i=0; i<hours; i++) {
             data.teachers.forEach(t => { if(newTSched[t]) newTSched[t][d][p+i] = ''; });
             data.classes.forEach(c => { if(newCSched[c]) newCSched[c][d][p+i] = ''; });
             data.rooms.forEach(r => { if(newRSched[r]) newRSched[r][d][p+i] = ''; });
         }
     };

     const targetCardData = existingValue ? parseCellData(existingValue) : null;
     if (targetCardData && isCardLocked(targetCardData, targetDIdx, targetPIdx, targetBlockSize)) {
         return showToast("Hedefteki kart kilitli, üzerine bırakılamaz!", "error");
     }

     if (payload.source === 'pool') {
        const sourceHours = payload.card.hours;
        if (!canPlaceCard(payload.card.teachers, payload.card.classes, payload.card.rooms, targetPIdx, sourceHours, existingValue)) {
            return showToast("Hücre uygun değil veya kilitli/başka bir çakışma var!", "error");
        }

        if (existingValue) {
            executeRemoval(existingValue, targetBlockSize, targetDIdx, targetPIdx);
            targetCardData.hours = targetBlockSize; // Ensure hours is correct
            newUnplaced.push(targetCardData);
        }

        const cDataStr = JSON.stringify({ id: payload.card.id, teachers: payload.card.teachers, classes: payload.card.classes, rooms: payload.card.rooms, subject: payload.card.subject });
        executePlacement(cDataStr, sourceHours, targetDIdx, targetPIdx);
        newUnplaced = newUnplaced.filter(c => c.id !== payload.card.id);

        setUnplacedCourses(newUnplaced);
        setSchedules(newTSched); setClassSchedules(newCSched); setRoomSchedules(newRSched);
        return;
     }

     // Moving from timetable
     if (payload.sourceEntity === destEntity && payload.dIdx === targetDIdx && payload.pIdx === targetPIdx) return; 
     if (previewType === 'subject' && payload.sourceEntity !== destEntity) {
         return showToast("Dersler görünümünde kartlar başka bir derse taşınamaz!", "error");
     }

     const sourceCardData = parseCellData(payload.targetValue);
     const sourceHours = payload.blockSize;

     if (sourceCardData && isCardLocked(sourceCardData, payload.dIdx, payload.pIdx, sourceHours)) {
         return showToast("Taşıdığınız kart kilitli!", "error");
     }

     if (sourceCardData && !canPlaceCard(sourceCardData.teachers, sourceCardData.classes, sourceCardData.rooms, targetPIdx, sourceHours, existingValue)) {
         return showToast("Hedef alanda başka bir çakışma var!", "error");
     }

     if (payload.targetValue) {
         executeRemoval(payload.targetValue, sourceHours, payload.dIdx, payload.pIdx);
     }

     if (existingValue) {
         executeRemoval(existingValue, targetBlockSize, targetDIdx, targetPIdx);
         targetCardData.hours = targetBlockSize;
         targetCardData.failCount = 0;
         if (!targetCardData.id) targetCardData.id = generateId();
         newUnplaced.push(targetCardData);
     }

     if (payload.targetValue) {
         executePlacement(payload.targetValue, sourceHours, targetDIdx, targetPIdx);
     }

     setUnplacedCourses(newUnplaced);
     setSchedules(newTSched); setClassSchedules(newCSched); setRoomSchedules(newRSched);
  };

