                                                          <span className="font-black text-slate-800 text-[10px] md:text-xs leading-none text-center truncate w-full px-1">{topText}</span>
                                                          <span className="font-bold text-[8px] md:text-[9px] text-slate-600 mt-0.5 truncate w-full text-center mix-blend-color-burn px-1">{bottomText}</span>
                                                          {subText && <span className="font-medium text-[7px] md:text-[8px] text-slate-500 italic truncate max-w-full mix-blend-color-burn">{subText}</span>}

                                                          {isLocked && <div className="absolute top-0.5 right-0.5 text-slate-800/50"><Lock className="w-3 h-3" /></div>}

                                                          <div className="absolute inset-0 bg-black/5 opacity-0 group-hover/cell:opacity-100 transition-opacity flex items-center justify-center gap-2 pointer-events-none">
                                                             <button className="pointer-events-auto p-1 bg-white/90 rounded text-slate-700 hover:text-blue-600 shadow-sm" title="Kartı Düzenle" onClick={(e) => { e.stopPropagation(); editPoolCard({...cData, hours: blockSize}); setPoolMenuOpen(true); }}><Edit2 className="w-3 h-3"/></button>
                                                             <button className="pointer-events-auto p-1 bg-white/90 rounded text-slate-700 hover:text-indigo-600 shadow-sm" title="Kilitle/Aç" onClick={(e) => toggleLock(e, lockEntity, absDIdx, pIdx, blockSize)}><Lock className="w-3 h-3"/></button>
                                                          </div>
                                                       </div>
                                                   </td>
                                               );
                                               pIdx += blockSize;
                                           } else {
                                               cells.push(
                                                   <td key={`${rowKey}-${absDIdx}-${pIdx}`} 
                                                       className={`border-r border-slate-200 p-0 ${isClosed ? 'bg-red-50' : 'bg-white hover:bg-slate-50'}`}
                                                       onDragOver={e => e.preventDefault()}
                                                       onDrop={e => handleDropToTimetable(e, rowKey, absDIdx, pIdx, 1, '')}>
                                                      <div className="h-full w-full min-h-[44px] md:min-h-[52px] flex items-center justify-center text-slate-300">
                                                          {isClosed ? <Ban className="w-4 h-4 text-red-300"/> : '·'}
                                                      </div>
                                                   </td>
                                               );
                                               pIdx++;
                                           }
                                       }
                                       return cells;
                                    })}
                                 </tr>
                               )
                            });
                         })()}
                      </tbody>
                   </table>
                </div>
             </div>
          </div>
        ) : mainTab === 'duty' ? (
          <div className="h-full bg-white rounded-xl shadow-sm border border-slate-200 p-6 flex flex-col h-[calc(100vh-140px)]">
             <DutyManager teachers={teachers} schedules={schedules} schoolSettings={schoolSettings} />
          </div>
        ) : (
          renderSettings()
        )}
      </div>
      <div className="bg-[#111827] border-t border-slate-800 px-4 py-2 flex flex-col sm:flex-row justify-between items-center text-[10px] text-slate-400 font-medium shrink-0 gap-1 relative z-[60]">
        <div>
          <span>Kuantum Pro © {new Date().getFullYear()}</span>
        </div>
        <div>
          <span>Geliştirici: <strong className="text-indigo-400">Bahadır Şafak Kumcu</strong></span>
        </div>
      </div>
    </div>
  );
}

export default App;
